// TabManager 实现：标签增删选、CEF 生命周期回调与可见性布局
#include "tab_manager.h" // 自身声明
#include "include/wrapper/cef_helpers.h" // CEF_REQUIRE_UI_THREAD
#include "app_window.h" // AppWindow 接口
#include "server/cdp_client.h" // CdpClient
#include "utils/logging.h" // 文件日志
TabManager::TabManager(AppWindow* window) : window_(window) {} // 绑定外壳窗口
int TabManager::InsertSlot(const CefRefPtr<AppHandler>& handler, const std::wstring& url, int index) { BrowserTab tab; tab.handler = handler; tab.url = url; if (index < 0 || index >= static_cast<int>(tabs_.size())) { tabs_.push_back(tab); return static_cast<int>(tabs_.size()) - 1; } tabs_.insert(tabs_.begin() + index, tab); if (active_ >= index) ++active_; return index; } // 插入槽位：尾部追加或在 index 处插入并右移活动下标
int TabManager::AddTab(const std::wstring& url, int index) { CEF_REQUIRE_UI_THREAD(); CefRefPtr<AppHandler> handler = new AppHandler(window_); const std::wstring target = url.empty() ? std::wstring(L"about:blank") : url; const int slot = InsertSlot(handler, target, index); LOG_INFO("tab", QStringLiteral("新建标签：槽位=%1，地址=%2").arg(slot).arg(QString::fromStdWString(target))); CefWindowInfo info; const RECT area = window_->BrowserArea(); info.SetAsChild(window_->HostHwnd(), CefRect(area.left, area.top, area.right - area.left, area.bottom - area.top)); CefBrowserSettings settings; CefBrowserHost::CreateBrowser(info, handler, target, settings, nullptr, nullptr); if (index < 0) active_ = slot; window_->OnTabsChanged(); return slot; } // 异步建页（CreateBrowser + OnAfterCreated）：避免 CreateBrowserSync 在 CEF 消息循环启动前重入死锁；父级必须是承载区原生窗口而不是主窗口，否则会被 Qt 覆盖整个客户区的原生子窗口遮住导致白屏；返回时 browser 尚为 nullptr，调用方须容忍
bool TabManager::Select(int index) { CEF_REQUIRE_UI_THREAD(); if (index < 0 || index >= static_cast<int>(tabs_.size())) return false; active_ = index; ApplyVisibility(); LayoutActive(); window_->OnTabsChanged(); return true; } // 切换活动标签并刷新可见性与布局
bool TabManager::Close(int index) { CEF_REQUIRE_UI_THREAD(); if (index < 0 || index >= static_cast<int>(tabs_.size())) { LOG_WARN("tab", QStringLiteral("关闭标签越界：index=%1，总数=%2").arg(index).arg(static_cast<int>(tabs_.size()))); return false; } LOG_INFO("tab", QStringLiteral("关闭标签：index=%1").arg(index)); BrowserTab tab = tabs_[index]; if (tab.browser == nullptr) { tabs_.erase(tabs_.begin() + index); if (active_ >= index) --active_; window_->OnTabsChanged(); return true; } window_->BeginBrowserClose(); CefRefPtr<CefBrowser> browser = tab.browser; tabs_.erase(tabs_.begin() + index); if (active_ >= index) --active_; if (active_ >= static_cast<int>(tabs_.size())) active_ = static_cast<int>(tabs_.size()) - 1; if (tabs_.empty()) { window_->ScheduleTabRestore(); } else { ApplyVisibility(); LayoutActive(); } window_->OnTabsChanged(); browser->GetHost()->CloseBrowser(true); return true; } // 先移除 UI 标签再强制销毁浏览器：CEF windowed 下 OnBeforeClose 常不回调，若只调 CloseBrowser 标签数会只增不减；已拷贝 browser 句柄，OnBrowserClosed 再回调时找不到标签属预期
BrowserTab* TabManager::Active() { return At(active_); } // 活动标签
BrowserTab* TabManager::At(int index) { if (index < 0 || index >= static_cast<int>(tabs_.size())) return nullptr; return &tabs_[index]; } // 按下标取标签（越界回 nullptr）
BrowserTab* TabManager::Find(CefRefPtr<CefBrowser> browser) { if (browser == nullptr) return nullptr; for (BrowserTab& tab : tabs_) { if (tab.browser != nullptr && tab.browser->GetIdentifier() == browser->GetIdentifier()) return &tab; } return nullptr; } // 按浏览器标识找标签
void TabManager::OnBrowserCreated(CefRefPtr<CefBrowser> browser, CefRefPtr<AppHandler> handler) { CEF_REQUIRE_UI_THREAD(); LOG_INFO("tab", QStringLiteral("标签浏览器就绪，标识=%1").arg(browser != nullptr ? browser->GetIdentifier() : 0)); for (size_t i = 0; i < tabs_.size(); ++i) { BrowserTab& tab = tabs_[i]; if (tab.browser == nullptr && tab.handler.get() == handler.get()) { tab.browser = browser; tab.handler = handler; tab.hwnd = browser->GetHost()->GetWindowHandle(); tab.cdp = new CdpClient(browser); tab.cdp->Attach(); if (active_ < 0) active_ = static_cast<int>(i); ApplyVisibility(); LayoutActive(); window_->OnTabsChanged(); return; } } BrowserTab tab; tab.handler = handler; tab.browser = browser; tab.hwnd = browser->GetHost()->GetWindowHandle(); tab.cdp = new CdpClient(browser); tab.cdp->Attach(); tabs_.push_back(tab); if (active_ < 0) active_ = static_cast<int>(tabs_.size()) - 1; ApplyVisibility(); LayoutActive(); window_->OnTabsChanged(); } // 异步建页完成：填 browser/hwnd/cdp 并补可见性、布局与 UI 同步；兜底挂到末尾
void TabManager::OnBrowserClosed(CefRefPtr<CefBrowser> browser) { CEF_REQUIRE_UI_THREAD(); window_->EndBrowserClose(); for (size_t i = 0; i < tabs_.size(); ++i) { if (tabs_[i].browser != nullptr && tabs_[i].browser->GetIdentifier() == browser->GetIdentifier()) { tabs_.erase(tabs_.begin() + static_cast<long>(i)); if (static_cast<int>(i) <= active_) --active_; break; } } if (active_ >= static_cast<int>(tabs_.size())) active_ = static_cast<int>(tabs_.size()) - 1; if (active_ < 0 && !tabs_.empty()) active_ = 0; if (tabs_.empty()) { if (closing_all_) { window_->OnAllTabsClosed(); return; } window_->ScheduleTabRestore(); return; } ApplyVisibility(); LayoutActive(); window_->OnTabsChanged(); } // 浏览器销毁：移除标签、修正活动下标；空且非关闭流程时经消息循环补建（OnBeforeClose 内不能再建浏览器）
void TabManager::EnsureOneTab() { if (closing_all_ || !tabs_.empty()) return; AddTab(std::wstring(L"https://www.bing.com"), -1); } // 关掉最后一个标签后不留空窗口：回到起始页，保持 sidecar 可继续接收指令
void TabManager::ApplyVisibility() { CEF_REQUIRE_UI_THREAD(); for (size_t i = 0; i < tabs_.size(); ++i) { BrowserTab& tab = tabs_[i]; if (tab.hwnd == nullptr || !::IsWindow(tab.hwnd) || tab.browser == nullptr) continue; const bool active = (static_cast<int>(i) == active_); ::ShowWindow(tab.hwnd, active ? SW_SHOW : SW_HIDE); tab.browser->GetHost()->WasHidden(!active); } } // 只显示活动标签，其余隐藏并 WasHidden 省渲染
void TabManager::LayoutActive() { CEF_REQUIRE_UI_THREAD(); const RECT area = window_->BrowserArea(); for (BrowserTab& tab : tabs_) { if (tab.hwnd == nullptr || !::IsWindow(tab.hwnd) || tab.browser == nullptr) continue; ::MoveWindow(tab.hwnd, area.left, area.top, area.right - area.left, area.bottom - area.top, TRUE); tab.browser->GetHost()->WasResized(); } } // 按承载区当前尺寸移动标签窗口并通知 resize（坐标相对承载区，建页时尺寸不准会在 OnBrowserCreated 再对一次）
void TabManager::CloseAll() { CEF_REQUIRE_UI_THREAD(); closing_all_ = true; bool any_open = false; for (BrowserTab& tab : tabs_) { if (tab.browser != nullptr) { any_open = true; tab.browser->GetHost()->CloseBrowser(true); } } if (!any_open) window_->OnAllTabsClosed(); } // 关闭全部标签并置位关闭标记；无活动浏览器时直接触发全关回调
